#!/usr/bin/env python3
"""Apply The Dispatch live billing session/host patch to server.js + app.js in-place."""
import base64, pathlib, subprocess, sys
root = pathlib.Path.cwd()
server = root / "server.js"
app = root / "app.js"
if not server.exists() or not app.exists():
    sys.exit("Run from the Replit project root containing server.js and app.js")
text = server.read_text()
if "function canonicalPublicOrigin()" in text:
    print("Already applied — nothing to do")
    sys.exit(0)
(server.with_suffix(server.suffix + ".bak-billing")).write_bytes(server.read_bytes())
(app.with_suffix(app.suffix + ".bak-billing")).write_bytes(app.read_bytes())
(root / "server.js.patch").write_bytes(base64.b64decode(''))
(root / "app.js.patch").write_bytes(base64.b64decode(''))
for p in ("server.js.patch", "app.js.patch"):
    r = subprocess.run(["patch", "-p0", "-i", p], cwd=root)
    if r.returncode != 0:
        sys.exit(f"patch failed: {p}")
r = subprocess.run(["node", "--check", "server.js"], cwd=root)
if r.returncode != 0:
    sys.exit("node --check server.js failed")
print("OK: billing session/host patch applied. Backups: *.bak-billing")
print("Next: set DISPATCH_PUBLIC_ORIGIN=https://thedispatch.uk and redeploy.")
